"""시작 폴더의 입력/센서_입력.json 을 만든다(사례 12건, N01~N12).
칸의 모양과 정상 부근 값은 05회차 실습 2의 입력과 같다(1일차 기술사실표의 /api/state 응답과 응답 모양).
열두 건의 값과 메모는 증거가 맞는 경우, 엇갈리는 경우, 모자란 경우를 고루 보이려고 새로 든 대어 보는 값이다.
트립 사례의 값은 온톨로지의 패턴 규칙(PS1 < 130 bar, VS1 >= 2.0 mm/s)과 인터록 기준(TS1 > 65 ℃) 쪽에 두었다.
사용: python3 입력_만들기.py <내보낼 파일>"""
import json, sys
SPEC = [('CE', 'avg', 30, 3), ('VS1', 'avg', 120, 3), ('VS1', 'max-min', 300, 3), ('TS1', 'avg', 120, 3), ('TS4', 'avg', 120, 12), ('PS1', 'avg', 120, 3), ('FS1', 'avg', 120, 3)]
def cov(win, limit, gap): return {'samples': win if limit == 3 else win // 10 + 6, 'max_gap_s': gap, 'limit_s': limit, 'covered': True}
def none(limit): return {'value': None, 'coverage': {'samples': 0, 'max_gap_s': None, 'limit_s': limit, 'covered': False}}
def case(no, asset, pattern, at, age, vals, memo, gaps=None, over=None):
    gaps = gaps or [1.004, 1.009, 1.012, 1.006, 11.002, 1.008, 1.005]; rs = []
    for (tag, agg, win, limit), v, g in zip(SPEC, vals, gaps):
        r = {'tag': tag, 'aggregate': agg, 'windowSeconds': win, 'value': v, 'coverage': cov(win, limit, g)}
        k = f'{tag}/{agg}'
        if over and k in over: r['value'] = over[k]['value']; r['coverage'] = over[k]['coverage']
        rs.append(r)
    return {'번호': no, '설비': asset, '경보_패턴': pattern, '판단_시각': at, 'freshness': {'tag': 'TS1', 'age_s': age, 'max_age_s': 60, 'ok': age <= 60}, 'readings': rs, '메모': memo}
C = [
 case('N01', 'HYD-01', 'COOLER_DEGRADATION', '2026-10-19 09:42:11', 0.7, [52.3, 0.59, 0.04, 59.1, 28.6, 181.1, 8.91], '주간조. 지난주에 쿨러 주변에서 분진이 나는 작업이 있었다.'),
 case('N02', 'HYD-02', 'COOLER_DEGRADATION', '2026-10-19 15:08:37', 0.6, [61.0, 0.62, 0.05, 58.3, 37.4, 180.7, 8.90], '오후에 캐비닛 환기 팬 필터를 교체하느라 환기를 잠시 멈췄다.', [1.005, 1.010, 1.011, 1.004, 10.997, 1.007, 1.003]),
 case('N03', 'HYD-03', 'COOLER_DEGRADATION', '2026-10-20 10:15:52', 0.8, [63.5, 0.97, 0.09, 57.9, 29.4, 181.0, 8.92], '순찰자가 쿨러 팬 벨트가 느슨해 보인다고 전했다. 쿨러 핀은 지난달에 세척했다.', [1.003, 1.008, 1.012, 1.006, 11.001, 1.005, 1.004]),
 case('N04', 'HYD-01', 'OVERHEAT_TRIP', '2026-10-20 14:33:09', 0.5, [74.2, 0.60, 0.04, 66.8, 30.1, 0.4, 0.0], '과열 인터록으로 설비가 멈춘 직후. 멈추기 전까지 부하를 높여 연속 운전했다.', [1.004, 1.007, 1.010, 1.005, 11.003, 1.009, 1.006]),
 case('N05', 'HYD-02', 'PUMP_LEAKAGE', '2026-10-21 08:20:44', 0.9, [83.7, 0.58, 0.03, 49.0, 27.8, 161.8, 8.0], '경보가 뜬 뒤 유량이 기준 곁에서 오르내렸다.', [1.006, 1.009, 1.013, 1.004, 10.999, 1.010, 1.007]),
 case('N06', 'HYD-03', 'LOW_PRESSURE_TRIP', '2026-10-21 13:47:26', 0.6, [84.0, 0.57, 0.03, 48.5, 27.9, 127.4, 6.1], '저압 인터록으로 설비가 멈추었다. 멈추기 전부터 프레스 사이클이 길어졌다는 연락이 있었다.', [1.005, 1.008, 1.011, 1.006, 11.000, 1.012, 1.009]),
 case('N07', 'HYD-01', 'FAN_VIBRATION', '2026-10-22 09:05:18', 0.7, [79.6, 1.27, 0.27, 53.8, 28.5, 181.2, 8.92], '팬 진동 경보와 같은 때에 유온도 평소보다 높았다.', [1.004, 1.011, 1.012, 1.005, 11.002, 1.006, 1.004]),
 case('N08', 'HYD-02', 'HIGH_VIBRATION_TRIP', '2026-10-22 16:29:53', 0.8, [82.4, 2.06, 0.31, 49.0, 28.1, 0.3, 0.0], '고진동 인터록으로 멈춘 뒤 진동 센서 쪽 수집이 한동안 끊겼다.', [1.005, 1.010, 1.012, 1.006, 10.998, 1.008, 1.005],
      over={'VS1/max-min': {'value': 0.31, 'coverage': {'samples': 112, 'max_gap_s': 96.4, 'limit_s': 3, 'covered': False}}}),
 case('N09', 'HYD-03', 'COOLER_DEGRADATION', '2026-10-23 11:11:40', 142.0, [55.8, 0.58, 0.04, 59.7, 28.4, 181.3, 8.91], '수집 서버를 점검한 뒤 화면의 값이 한동안 바뀌지 않았다.'),
 case('N10', 'HYD-01', 'COOLER_DEGRADATION', '2026-10-26 10:02:35', 0.6, [64.8, 0.95, 0.08, 57.2, None, 181.0, 8.91], '캐비닛 온도 센서를 교정하러 떼어 낸 상태다. 팬 쪽에서 소리가 난다는 말이 있었다.', [1.004, 1.009, 1.011, 1.005, 11.002, 1.007, 1.004],
      over={'TS4/avg': none(12)}),
 case('N11', 'HYD-02', 'PUMP_LEAKAGE', '2026-10-27 14:55:02', 0.7, [83.9, 0.58, 0.03, 48.8, 27.7, 172.4, 8.6], '경보는 한 번 떴다가 꺼졌다. 같은 시간대에 금형을 바꾸느라 부하가 낮았다.', [1.005, 1.008, 1.010, 1.004, 11.001, 1.009, 1.006]),
 case('N12', 'HYD-03', 'OIL_ANALYSIS', '2026-10-28 09:30:00', 0.8, [84.2, 0.58, 0.03, 48.1, 27.9, 181.4, 8.92], '분기 오일 분석에서 수분이 기준을 넘었다고 보전 담당자가 입력했다. 다른 항목의 결과는 아직 들어오지 않았다.', [1.004, 1.008, 1.011, 1.005, 10.999, 1.006, 1.004]),
]
open(sys.argv[1], 'w', encoding='utf-8').write(json.dumps(C, ensure_ascii=False, indent=1) + '\n')
print(len(C), sum(len(c['readings']) for c in C))
